import{_ as a,c as e,o as r,ag as d}from"./chunks/framework._xRlcm3f.js";const g=JSON.parse('{"title":"使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md","lastUpdated":1790228279000}'),i={name:"guide/usage.md"};function l(h,t,s,n,u,o){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><p>发布工具把「写」和「发」分开：文档照常在思源里写，发布配置与发布状态都收在插件的面板里。</p><h2 id="三种发布方式" tabindex="-1">三种发布方式 <a class="header-anchor" href="#三种发布方式" aria-label="Permalink to &quot;三种发布方式&quot;">​</a></h2><p>按使用频率排序，先看第一种就能用起来。</p><table tabindex="0"><thead><tr><th>方式</th><th>适合场景</th><th>文档</th></tr></thead><tbody><tr><td><strong>快速发布</strong></td><td>选个平台就发，接受默认参数</td><td><a href="/siyuan-plugin-publisher/guide/quick-publish.html">快速发布</a></td></tr><tr><td><strong>详细发布</strong></td><td>需要调标题、摘要、标签、分类、别名等</td><td><a href="/siyuan-plugin-publisher/guide/single-publish.html">详细发布</a></td></tr><tr><td><strong>批量分发</strong></td><td>同一篇文档一次发到多个平台</td><td><a href="/siyuan-plugin-publisher/guide/batch-publish.html">批量分发</a></td></tr></tbody></table><h2 id="配合使用的功能" tabindex="-1">配合使用的功能 <a class="header-anchor" href="#配合使用的功能" aria-label="Permalink to &quot;配合使用的功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th><th>文档</th></tr></thead><tbody><tr><td>文章管理</td><td>集中列出与操作已发布、未发布文档；可按发布源笔记本隔离范围</td><td><a href="/siyuan-plugin-publisher/guide/article-manage.html">文章管理</a></td></tr><tr><td>发布设置</td><td>平台账号、图床、偏好与 AI 设置</td><td><a href="/siyuan-plugin-publisher/guide/settings.html">发布设置</a></td></tr><tr><td>分类体系</td><td>平台的分类 / 专栏 / 文集如何选取</td><td><a href="/siyuan-plugin-publisher/guide/categories.html">分类体系</a></td></tr><tr><td>AI 辅助</td><td>自动生成标题、摘要、标签与分类</td><td><a href="/siyuan-plugin-publisher/guide/ai.html">AI 辅助</a></td></tr><tr><td>常见问题</td><td>Cookie 过期、图片处理、平台限制与排查</td><td><a href="/siyuan-plugin-publisher/guide/faq.html">常见问题</a></td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li><strong>安装并启用插件</strong>：在思源插件市场安装「发布工具」。</li><li><strong>配好第一个平台</strong>：打开面板 → 设置 → 账号设置 → 添加账号，填完字段后点「验证」，状态显示「运行中」即可。</li><li><strong>发布第一篇</strong>：回到快速发布，选刚配好的平台，点「发布」。</li></ol><div class="tip custom-block"><p class="custom-block-title">需要精细控制时</p><p>在快速发布的卡片上点「详细发布」，可以逐项调整标题、摘要、标签、分类与别名。</p></div><h2 id="界面说明" tabindex="-1">界面说明 <a class="header-anchor" href="#界面说明" aria-label="Permalink to &quot;界面说明&quot;">​</a></h2><p>插件以原生面板挂在思源内，跟随思源的深浅色主题。同一套界面同时用于插件本体与四个 web 产物（挂件、浏览器扩展、nginx、vercel）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>你的平台在不在支持列表：<a href="/siyuan-plugin-publisher/platforms/">平台支持</a></li><li>想接一个新平台：<a href="/siyuan-plugin-publisher/dev/">插件开发</a></li></ul>',14)])])}const b=a(i,[["render",l]]);export{g as __pageData,b as default};
